import{_ as s,o as t,c as a,ah as i}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"SMS et WhatsApp","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/sms-whatsapp.md","filePath":"src/guide/admin/sms-whatsapp.md"}'),r={name:"guide/admin/sms-whatsapp.md"};function n(o,e,l,p,u,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="sms-et-whatsapp" tabindex="-1">SMS et WhatsApp <a class="header-anchor" href="#sms-et-whatsapp" aria-label="Permalink to &quot;SMS et WhatsApp&quot;">​</a></h1><p>Les notifications aux familles arrivent dans l&#39;application et par e-mail. Avec cette option, certaines peuvent aussi partir <strong>par SMS ou sur WhatsApp</strong>, sur le téléphone des parents qui ont donné leur numéro. C&#39;est utile pour les familles qui consultent peu leurs e-mails.</p><p>La page s&#39;ouvre par <strong>Administration → SMS et WhatsApp</strong>. Elle n&#39;est visible que par les administrateurs, et seulement si votre licence comprend le pôle <strong>Relations familles</strong>.</p><h2 id="un-operateur-des-credits" tabindex="-1">Un opérateur, des crédits <a class="header-anchor" href="#un-operateur-des-credits" aria-label="Permalink to &quot;Un opérateur, des crédits&quot;">​</a></h2><p>Les messages passent par un opérateur SMS ou WhatsApp. Chaque message consomme un crédit acheté auprès de cet opérateur. Les crédits ne sont pas compris dans la licence ERA : ils s&#39;achètent séparément, sur devis. Contactez edPage pour activer l&#39;option.</p><p>Tant qu&#39;aucun opérateur n&#39;est raccordé, la page affiche <strong>Pas d&#39;opérateur</strong> : les familles restent prévenues dans l&#39;application et par e-mail, comme d&#39;habitude.</p><div class="info custom-block"><p class="custom-block-title">Établissements hébergés sur Era Admission</p><p>L&#39;option n&#39;est pas encore proposée aux établissements hébergés sur la plateforme partagée. Elle concerne pour l&#39;instant les installations propres à un établissement.</p></div><h3 id="le-mode-pilote" tabindex="-1">Le mode pilote <a class="header-anchor" href="#le-mode-pilote" aria-label="Permalink to &quot;Le mode pilote&quot;">​</a></h3><p>Avant le choix définitif de l&#39;opérateur, edPage peut activer un <strong>mode pilote</strong>. Aucun message ne part réellement : chacun est écrit dans le journal de l&#39;application. Tout le reste fonctionne comme avec un opérateur (qui reçoit quoi, le décompte du mois). C&#39;est l&#39;occasion de choisir les notifications à envoyer et de vérifier que les parents ont renseigné leur numéro.</p><h2 id="choisir-ce-qui-part-par-telephone" tabindex="-1">Choisir ce qui part par téléphone <a class="header-anchor" href="#choisir-ce-qui-part-par-telephone" aria-label="Permalink to &quot;Choisir ce qui part par téléphone&quot;">​</a></h2><ol><li>Si l&#39;opérateur propose les deux, choisissez <strong>Envoyer par</strong> : SMS ou WhatsApp.</li><li>Sous <strong>Notifications envoyées</strong>, cochez celles qui partent aussi sur le téléphone : absence non justifiée, bulletin publié, paiement enregistré, etc. Seules les notifications destinées aux familles sont proposées : celles du personnel ne partent jamais par SMS.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Par défaut, aucune n&#39;est cochée. Chaque message coûtant un crédit, gardez celles qui comptent vraiment pour les familles.</p><p>Le message reprend le titre et le texte de la notification, dans la langue choisie par le parent. Un SMS est limité à 306 caractères, un message WhatsApp à 1 000 : au-delà, il est coupé.</p><h2 id="qui-recoit-les-messages" tabindex="-1">Qui reçoit les messages <a class="header-anchor" href="#qui-recoit-les-messages" aria-label="Permalink to &quot;Qui reçoit les messages&quot;">​</a></h2><p>Un parent reçoit une notification par téléphone si les trois conditions sont réunies :</p><ul><li>l&#39;établissement envoie ce type de notification (case cochée ci-dessus) ;</li><li>le parent a un <strong>numéro de téléphone</strong> sur son compte ;</li><li>il n&#39;a pas désactivé l&#39;envoi par téléphone pour ce type, dans ses préférences.</li></ul><p>Le numéro vient de deux endroits :</p><ul><li><strong>le dossier de candidature</strong> : à l&#39;approbation d&#39;une admission, le numéro du tuteur est reporté sur son compte parent, s&#39;il n&#39;en avait pas déjà un ;</li><li><strong>le parent lui-même</strong>, dans <strong>Paramètres → Profil</strong> (voir <a href="/era-guide/guide/prise-en-main.html#parametres-du-compte">Prise en main</a>).</li></ul><p>Un administrateur peut aussi le saisir ou le corriger depuis la fiche de l&#39;utilisateur, dans <a href="/era-guide/guide/admin/personnel-utilisateurs.html">Personnel et comptes utilisateurs</a>. Les numéros s&#39;écrivent avec l&#39;indicatif du pays (par exemple <code>+228 90 11 22 33</code>). Sans indicatif, celui du Togo (+228) est ajouté.</p><h2 id="suivre-les-envois" tabindex="-1">Suivre les envois <a class="header-anchor" href="#suivre-les-envois" aria-label="Permalink to &quot;Suivre les envois&quot;">​</a></h2><p>Le bas de la page indique combien de messages sont partis ce mois-ci, et combien l&#39;opérateur en a refusé (crédit épuisé, numéro invalide...). Les 20 derniers envois sont listés avec la date, le destinataire, son numéro, la notification et le statut <strong>Envoyé</strong> ou <strong>Refusé</strong>. Survolez un statut <strong>Refusé</strong> pour voir la raison donnée par l&#39;opérateur.</p><p>Un message refusé n&#39;est pas renvoyé. La notification, elle, est bien arrivée dans l&#39;application et, selon les préférences du parent, par e-mail.</p><p>Ce journal est effacé après 13 mois.</p>',23)])])}const h=s(r,[["render",n]]);export{m as __pageData,h as default};
